INSERT INTO curated_question_catalog (source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,content_status,is_original,didactic_provenance) SELECT source_id,syllabus_topic_id,'pcac-2026-autoral-regencia-rogar-servir-20261121','PC-AC 2026',2026,'Oficial Investigador de Polícia','AUTORAL','Língua Portuguesa','Transitividade verbal e objeto indireto',E'Considere a frase: "O candidato rogou ao atendente uma orientação e pediu que lhe entregasse o formulário."\n\nAssinale a alternativa correta quanto às funções sintáticas dos termos.\nA) "Ao atendente" é objeto direto de "rogou".\nB) "Uma orientação" é objeto indireto de "rogou".\nC) "Rogou" é verbo intransitivo nesse contexto.\nD) "Lhe" é objeto direto de "entregasse".\nE) "Ao atendente" é objeto indireto de "rogou", e "uma orientação" é seu objeto direto.','E','A alternativa E é correta. Quem roga, roga algo (objeto direto: uma orientação) a alguém (objeto indireto: ao atendente). Na segunda oração, entregar o formulário a alguém: formulário é objeto direto, lhe é objeto indireto. A está errada porque ao atendente tem preposição e designa destinatário; B inverte os complementos; C ignora os dois complementos; D confunde lhe (destinatário) com objeto direto. Dica: pergunte o quê? e a quem? ao verbo.','active',true,'{"authored":true,"not_official_exam":true,"source":"Norte Concursos — questão autoral corrigida a partir do tópico de regência","editorial_review_status":"approved","original_screenshot_question_remains_under_review":true,"trainer_release_blocked":false}'::jsonb FROM curated_question_catalog WHERE external_item_key='user-capture-20261121-portugues-rogo-lhe-servir-nos' AND NOT EXISTS (SELECT 1 FROM curated_question_catalog WHERE external_item_key='pcac-2026-autoral-regencia-rogar-servir-20261121');